expansions.body:
docker exec -i -e PGDATABASE='shop' 'pg-main' sh -c 'if [ -n "${POSTGRES_PASSWORD_FILE:-}" ] && [ -r "$POSTGRES_PASSWORD_FILE" ]; then PGPASSWORD=$(cat "$POSTGRES_PASSWORD_FILE"); else PGPASSWORD="${POSTGRES_PASSWORD:-${POSTGRESQL_PASSWORD:-}}"; fi; export PGPASSWORD; exec psql -X -q -tA -F "	" -v ON_ERROR_STOP=1 -U "${POSTGRES_USER:-${POSTGRESQL_USERNAME:-postgres}}" -f -' <<'VPSCFG_SQL'
BEGIN;
SET LOCAL lock_timeout = '10s';
SELECT 'pending ' || k || ' ' || count(*) FROM (SELECT CASE c.relkind WHEN 'v' THEN 'view' WHEN 'm' THEN 'matview' WHEN 'S' THEN 'sequence' ELSE 'table' END AS k FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'sales' AND c.relkind IN ('r', 'p', 'v', 'm', 'S') AND pg_get_userbyid(c.relowner) <> 'app_owner') s GROUP BY k ORDER BY k;
SELECT 'pending schema 1' FROM pg_namespace WHERE nspname = 'sales' AND pg_get_userbyid(nspowner) <> 'app_owner';
DO $vpscfg$
DECLARE r record;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_owner') THEN
    RAISE EXCEPTION 'vpscfg: the role does not exist';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'sales') THEN
    RAISE EXCEPTION 'vpscfg: the schema does not exist';
  END IF;
  IF (SELECT pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname = 'sales') <> 'app_owner' THEN
    EXECUTE format('ALTER SCHEMA %I OWNER TO %I', 'sales', 'app_owner');
  END IF;
  FOR r IN SELECT c.relname, c.relkind FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'sales' AND c.relkind IN ('r', 'p', 'v', 'm') AND pg_get_userbyid(c.relowner) <> 'app_owner' ORDER BY c.relkind, c.relname LOOP
    EXECUTE format('ALTER %s %I.%I OWNER TO %I', CASE r.relkind WHEN 'v' THEN 'VIEW' WHEN 'm' THEN 'MATERIALIZED VIEW' ELSE 'TABLE' END, 'sales', r.relname, 'app_owner');
  END LOOP;
  FOR r IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'sales' AND c.relkind IN ('S') AND pg_get_userbyid(c.relowner) <> 'app_owner' ORDER BY c.relname LOOP
    EXECUTE format('ALTER SEQUENCE %I.%I OWNER TO %I', 'sales', r.relname, 'app_owner');
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'sales' AND c.relkind IN ('r', 'p', 'v', 'm', 'S') AND pg_get_userbyid(c.relowner) <> 'app_owner') THEN
    RAISE EXCEPTION 'vpscfg: objects are still not owned; rolled back';
  END IF;
END
$vpscfg$;
SELECT 'owned ' || count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'sales' AND c.relkind IN ('r', 'p', 'v', 'm', 'S');
COMMIT;
VPSCFG_SQL

expansions.check:
docker exec -i -e PGDATABASE=shop -e PGOPTIONS='-c default_transaction_read_only=on' pg-main sh -c 'if [ -n "${POSTGRES_PASSWORD_FILE:-}" ] && [ -r "$POSTGRES_PASSWORD_FILE" ]; then PGPASSWORD=$(cat "$POSTGRES_PASSWORD_FILE"); else PGPASSWORD="${POSTGRES_PASSWORD:-${POSTGRESQL_PASSWORD:-}}"; fi; export PGPASSWORD; exec psql -X -q -tA -F "	" -v ON_ERROR_STOP=1 -U "${POSTGRES_USER:-${POSTGRESQL_USERNAME:-postgres}}" -f -' <<'SQL'
BEGIN READ ONLY;
SET statement_timeout = '10s';
SELECT '@@@check';
SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'sales' AND pg_get_userbyid(nspowner) = 'app_owner') AND NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'sales' AND c.relkind IN ('r', 'p', 'v', 'm', 'S') AND pg_get_userbyid(c.relowner) <> 'app_owner') THEN 'VPSCFG-DONE' ELSE 'VPSCFG-NEEDED' END;
COMMIT;
SQL

